<div class="page-heading"><div><h1>Medicamentos</h1><p>Catálogo y existencias disponibles para la venta</p></div><?php if(\App\Core\Auth::isAdmin()):?><a class="btn btn-primary" href="<?=url('index.php?page=medicamento-form')?>"><i class="bi bi-plus-lg"></i> Registrar</a><?php endif?></div>
<div class="panel mb-4"><form class="row g-2"><input type="hidden" name="page" value="medicamentos"><div class="col-md-7"><input class="form-control" name="q" value="<?=e($buscar)?>" placeholder="Buscar por nombre, código o laboratorio"></div><div class="col-md-3"><select class="form-select" name="categoria"><option value="">Todas las categorías</option><?php foreach($categorias as$c):?><option value="<?=$c['id']?>" <?=selected($cat,$c['id'])?>><?=e($c['nombre'])?></option><?php endforeach?></select></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Buscar</button></div></form></div>
<div class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Código</th><th>Medicamento</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($medicamentos as$m):?><tr><td><span class="code-chip"><?=e($m['codigo'])?></span></td><td><strong><?=e($m['nombre'])?></strong><small class="d-block text-muted"><?=e(trim(($m['concentracion']??'').' · '.($m['presentacion']??''),' ·'))?></small></td><td><?=e($m['categoria'])?></td><td><?=money($m['precio_venta'])?></td><td><strong class="<?=$m['stock']<=$m['stock_minimo']?'text-danger':''?>"><?=$m['stock']?></strong> <small>/ mín. <?=$m['stock_minimo']?></small></td><td><span class="badge text-bg-<?=$m['activo']?'success':'secondary'?>"><?=$m['activo']?'Activo':'Inactivo'?></span></td><td class="text-nowrap"><?php if(\App\Core\Auth::isAdmin()):?><a class="btn btn-sm btn-light" href="<?=url('index.php?page=medicamento-form&id='.$m['id'])?>"><i class="bi bi-pencil"></i></a><form class="d-inline" method="post" action="<?=url('index.php?page=medicamento-toggle')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$m['id']?>"><button class="btn btn-sm btn-light" data-confirm="¿Cambiar el estado de este medicamento?"><i class="bi bi-power"></i></button></form><?php endif?></td></tr><?php endforeach?><?php if(!$medicamentos):?><tr><td colspan="7" class="empty-state">No se encontraron medicamentos</td></tr><?php endif?></tbody></table></div></div>
